const raw = $input.first().json;
const body = raw.body || raw;
const website = (body.website || '').trim();
if (!website) throw new Error('website is required');
const apify_token = (body.apify_token || process.env.APIFY_API_TOKEN || '').trim();
if (!apify_token) throw new Error('apify_token is required');
const max_pages = parseInt(body.max_pages || '10', 10);
const base = website.replace(/\/+$/, '');
const domain = website.replace(/^https?:\/\//, '').replace(/\/+$/, '');
const supabase_url = (body.supabase_url || process.env.SUPABASE_URL || '').trim();
const supabase_key = (body.supabase_key || process.env.SUPABASE_KEY || '').trim();
return [{ json: { website, domain, vendor_name: body.vendor_name || '', apify_token, max_pages, base, supabase_url, supabase_key } }];

const website = $('Validate Input').first().json.website;
const domain = $('Validate Input').first().json.domain;
const inputName = $('Validate Input').first().json.vendor_name || '';
const results = $input.first().json;
const items = Array.isArray(results) ? results : [results];

// Classify each page by URL path
function classifyPage(url) {
  const u = (url || '').toLowerCase();
  if (/\/pric|\/plans|\/pricing-plans/.test(u)) return 'PRICING PAGE';
  if (/\/feature|\/platform|\/product/.test(u)) return 'FEATURES PAGE';
  if (/\/integrat|\/marketplace|\/apps/.test(u)) return 'INTEGRATIONS PAGE';
  if (/\/customer|\/case-stud|\/success-stor/.test(u)) return 'CUSTOMERS PAGE';
  if (/\/about|\/company|\/team/.test(u)) return 'ABOUT PAGE';
  if (/\/solution|\/use-case/.test(u)) return 'SOLUTIONS PAGE';
  if (/\/securit|\/trust|\/compliance/.test(u)) return 'SECURITY PAGE';
  if (/\/contact|\/demo/.test(u)) return 'CONTACT PAGE';
  return null;
}

const TAGLINE_SUFFIXES = new Set(['analytics','automation','dashboard','insights','intelligence','management','monitoring','platform','reporting','software','solution','solutions','tracking']);
function isTagline(text) {
  const lower = (text||'').toLowerCase();
  if (TAGLINE_SUFFIXES.has(lower.split(/\s+/).pop())) return true;
  if (/\bai[- ]powered\b|\b\w+-powered\b|\bpowered by\b/.test(lower)) return true;
  if (/\b\d{4}\b/.test(lower)) return true;
  return false;
}
function cleanCandidate(raw) {
  let s = (raw||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  if (!s) return '';
  for (const sep of [' | ',' - ',' – ',' — ',': ']) {
    if (s.includes(sep)) { for (const p of s.split(sep)) { const c=cleanCandidate(p); if(c) return c; } }
  }
  if (isTagline(s)) return '';
  if (s.split(/\s+/).length > 5) return '';
  if (s.length > 40) return '';
  return s;
}
function domainStem(url) {
  try {
    const base = new URL(url).hostname.replace(/^www\./,'').split('.')[0].toLowerCase();
    for (const p of ['get','try','use','my','the']) {
      if (base.startsWith(p) && base.length-p.length >= 4)
        return base.slice(p.length).charAt(0).toUpperCase()+base.slice(p.length+1);
    }
    return base.charAt(0).toUpperCase()+base.slice(1);
  } catch { return ''; }
}

// Build pages array with classification
const pages = items.map(item => {
  const pageUrl = item.url || item.loadedUrl || '';
  const label = classifyPage(pageUrl);
  return {
    url: pageUrl,
    title: item.title || item.metadata?.title || '',
    text: (item.text || item.markdown || item.content || '').slice(0, 5000),
    label
  };
}).filter(p => p.url);

// Best name from homepage (unlabelled pages first)
let name = '';
for (const page of pages) {
  if (!page.label) {
    const c = cleanCandidate(page.title);
    if (c) { name = c; break; }
  }
}
if (!name) {
  for (const page of pages) {
    const c = cleanCandidate(page.title);
    if (c) { name = c; break; }
  }
}
if (!name) name = cleanCandidate(inputName) || domainStem(website);

// Combine: homepage text first, then labelled sections
const homepageText = pages.filter(p => !p.label).map(p => p.text).join(' ');
const sections = pages
  .filter(p => p.label && p.text.length > 50)
  .map(p => `\n\n[${p.label}]\n${p.text}`)
  .join('');

const pricing_page_found = pages.some(p => p.label === 'PRICING PAGE' && p.text.length > 100);
const allText = homepageText + sections;
const word_count = allText ? allText.split(/\s+/).length : 0;

return [{ json: { website, domain, name, word_count, text: allText.slice(0, 15000), pages, tier_used: 'tier3_wcc', ok: true, pricing_page_found, pages_fetched: pages.length } }];
